const themeSlug = "MS Stavby | Web (Copy)";

function clearForm(formId) {
  document.getElementById(formId).reset();
}
window.addEventListener("message", (event) => {
  if (event?.data?.zoom) {
    const mains = document.getElementsByTagName('main')
    for (let main of mains) {
      main.style.zoom = event?.data?.zoom
    }
  }
}, false);

async function form_e810fb378433(event) {
  event.preventDefault();
  const data = new FormData(event.target);
  const loader = JSAlert.loader("Please wait...");
  try {
    const formResponse = await fetch(
      `${window.location.origin}/wp-json/msstavby/v1/form`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          form: "form_e810fb378433",
          data: Object.fromEntries(data),
          slug: themeSlug,
        }),
      }
    );
    if (formResponse.status === 200) {
      loader.dismiss();
      const alert = new JSAlert("Form submitted successfully!").dismissIn(1000 * 7);
      alert.addButton("Ok");
      alert.setIcon(JSAlert.Icons.Success);
      alert.show();
    }
    clearForm("form_e810fb378433");
  } catch (err) {
    loader.dismiss();
    clearForm("form_e810fb378433");
  }
}


document.addEventListener('DOMContentLoaded', () => {
  // document.body.style.overflowX = "hidden" // Disabled - was causing rigid Figma-like layout

  // Initialize map-related variables BEFORE they are used
  let currentMapCategory = '0';
  let mapLoaded = false;

  // Lazy load Geo Mashup map via AJAX
  async function loadMapWithCategory(categoryId = '0') {
    const mapContainer = document.getElementById('geo-map-container');
    if (!mapContainer) return;

    // Show loading indicator
    mapContainer.innerHTML = '<div class="loading">Načítání mapy...</div>';

    // Build URL with category parameter
    const url = categoryId === '0' || !categoryId
      ? window.location.origin + '/wp-json/msstavby/v1/geo-map'
      : window.location.origin + '/wp-json/msstavby/v1/geo-map?category=' + categoryId;

    // Load map via AJAX
    return fetch(url)
      .then(response => {
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        return response.json();
      })
      .then(data => {
        if (data.hasOwnProperty('success') && data.success && data.html) {
          mapContainer.innerHTML = data.html;
          // Trigger any map initialization scripts
          if (typeof GeoMashup !== 'undefined' && typeof GeoMashup.init !== 'undefined') {
            GeoMashup.init();
          }
        } else if (data.hasOwnProperty('code') && data.code === 'plugin_missing') {
          mapContainer.innerHTML = '<div class="error">' + data.message + '</div>';
        }
      })
      .catch(error => {
        console.error('Error loading map:', error);
        mapContainer.innerHTML = '<div class="error">Chyba při načítání mapy</div>';
      });
  }

  // Load map with current category filter
  function lazyLoadGeoMap() {
    if (!mapLoaded) {
      const mapContainer = document.getElementById('geo-map-container');
      if (mapContainer && mapContainer.getAttribute('data-lazy-load') === 'true') {
	const mapObserver = new IntersectionObserver((entries, observer) => {
	  entries.forEach(entry => {
	    if (entry.isIntersecting) {
	      loadMapWithCategory(currentMapCategory).then(() => {
		mapLoaded = true;
	      });
	      observer.unobserve(entry.target);
	    }
	  });
	}, {
	  rootMargin: '200px 0px',
	  threshold: 0.1
	});

	mapObserver.observe(mapContainer);
      }
    }
  }

  // Map filter change handler
  const mapFilterRadios = document.querySelectorAll('input[name="map-filter"]');
  const mapFilterCheckboxes = document.querySelectorAll('input[type="checkbox"][name="map-filter"]');

  // Handle radio buttons (single selection mode)
  mapFilterRadios.forEach(radio => {
    radio.addEventListener('change', function() {
      if (this.checked) {
	const value = this.value;
	currentMapCategory = value;
	// Uncheck all checkboxes
	mapFilterCheckboxes.forEach(cb => cb.checked = false);
	// Reload the map immediately if already loaded
	if (mapLoaded) {
	  loadMapWithCategory(value);
	}
      }
    });
  });

  // Handle checkboxes
  mapFilterCheckboxes.forEach(checkbox => {
    checkbox.addEventListener('change', function() {
      // Uncheck the radio button when a checkbox is checked
      mapFilterRadios.forEach(radio => radio.checked = false);
      
      // Get all checked checkbox values
      const checkedValues = Array.from(mapFilterCheckboxes)
	.filter(cb => cb.checked)
	.map(cb => cb.value);
      
      // For map filtering, we use the first checked category (or 0 if none)
      currentMapCategory = checkedValues.length > 0 ? checkedValues[0] : '0';
      
      // Reload the map immediately if already loaded
      if (mapLoaded) {
	loadMapWithCategory(currentMapCategory);
      }
    });
  });

  lazyLoadGeoMap();

  // Search form toggle using WordPress jQuery
  if (typeof jQuery !== 'undefined') {
    jQuery('#searchbutt').click(function () {
      jQuery('#searchWrap').fadeToggle('slow', 'linear');
    });
  }

  // Click-to-reply functionality for comments
  if (typeof jQuery !== 'undefined') {
    jQuery('.comment-author-reply').click(function() {
      const commentLink = jQuery(this).data('comment-link');
      const authorName = jQuery(this).data('comment-author');
      const commentID = jQuery(this).data('comment-id');
      const $textarea = jQuery('textarea#comment');
      
      if ($textarea.length) {
        // Create @mention format
        const replyPrefix = '<a href="' + commentLink + '">@' + authorName + '</a>: ';
        const currentContent = $textarea.val();
        
        // Add reply prefix to beginning of textarea
        if (currentContent.length > 0) {
          $textarea.val(replyPrefix + currentContent);
        } else {
          $textarea.val(replyPrefix);
        }
        
        // Focus the textarea
        $textarea.focus();
        
        // Scroll to comment form
        jQuery('html, body').animate({
          scrollTop: jQuery('#respond').offset().top - 50
        }, 500);
        
        // Track reply event (DataLayer)
        if (typeof dataLayer !== 'undefined') {
          dataLayer.push({
            'event': 'reply',
            'reply': authorName,
            'comment_id': commentID
          });
        }
      }
      return false;
    });
  }

  // Categories Filter Functionality (chip buttons)
  const filterChips = document.querySelectorAll('.filter-chip');
  let selectedCategories = new Set();
  let allSelected = false;
  let currentPage = 1;

  // LocalStorage key for remembering filter state
  const STORAGE_KEY = 'msstavby_filter_state';

  function saveFilterState() {
    const state = {
      allSelected: allSelected,
      selectedCategories: Array.from(selectedCategories)
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }

  function loadFilterState() {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      try {
        const state = JSON.parse(stored);
        return state;
      } catch (e) {
        console.error('Error loading filter state:', e);
        return null;
      }
    }
    return null;
  }

  function updateURLParams() {
    const categoriesArray = allSelected ? [0] : Array.from(selectedCategories);
    const params = new URLSearchParams(window.location.search);

    if (allSelected || categoriesArray.length === 0) {
      params.delete('cat');
    } else {
      params.set('cat', categoriesArray.join(','));
    }

    const newURL = params.toString() ? `${window.location.pathname}?${params.toString()}` : window.location.pathname;
    window.history.replaceState({}, '', newURL);
  }

  function applyFilterFromParams(paramValue) {
    if (paramValue === null || paramValue === undefined) {
      // No URL param, load from localStorage
      const storedState = loadFilterState();
      if (storedState) {
        allSelected = storedState.allSelected;
        storedState.selectedCategories.forEach(catId => selectedCategories.add(catId));
      }
    } else if (paramValue === '0' || paramValue === '') {
      allSelected = true;
      selectedCategories.clear();
    } else {
      const catIds = paramValue.toString().split(',').map(id => parseInt(id)).filter(id => !isNaN(id));
      if (catIds.length > 0) {
        allSelected = false;
        selectedCategories.clear();
        catIds.forEach(catId => selectedCategories.add(catId));
      }
    }

    setTimeout(() => {
      filterPosts(1);
      saveFilterState();
      updateURLParams();
      updateFilterChipUI();
    }, 100);
  }

  function updateFilterChipUI() {
    // Update chip classes based on current filter state
    filterChips.forEach(chip => {
      const filter = chip.getAttribute('data-filter');
      const chipElement = chip;

      chipElement.classList.remove('filter-chip-active');

      if (allSelected && filter === 'all') {
        chipElement.classList.add('filter-chip-active');
      } else if (!allSelected && filter !== 'all') {
        const catId = parseInt(filter);
        if (!isNaN(catId) && selectedCategories.has(catId)) {
          chipElement.classList.add('filter-chip-active');
        }
      }
    });
  }

  function filterPosts(paged = 1, append = false, restoreScroll = false, scrollPosition = 0) {
    currentPage = paged;
    const categoriesArray = allSelected ? [0] : Array.from(selectedCategories);

    // Show loading state
    const projectsContainer = document.getElementById('projects');
    if (projectsContainer) {
      // Store current height to prevent container collapse
      const containerHeight = projectsContainer.offsetHeight;
      projectsContainer.innerHTML = '<div class="col-12 text-center py-5"><div class="spinner-border text-primary" role="status"><span class="visually-hidden">Načítání...</span></div></div>';
      // Maintain height while loading to prevent page jump
      projectsContainer.style.minHeight = containerHeight + 'px';
    }

    // Fetch filtered posts via AJAX
    fetch('/wp-json/msstavby/v1/filter-posts', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        categories: categoriesArray,
        posts_per_page: 6,
        paged: currentPage,
      })
    })
    .then(response => response.json())
    .then(data => {
      if (data.success && data.html) {
        if (projectsContainer) {
          if (append) {
            projectsContainer.insertAdjacentHTML('beforeend', data.html);
          } else {
            projectsContainer.innerHTML = data.html;
            // Restore scroll position after content update if requested
            if (restoreScroll) {
              window.scrollTo(0, scrollPosition);
            }
          }
          // Remove the fixed height after content is loaded
          projectsContainer.style.minHeight = '';
        }

        // Update
        const paginationContainer = document.getElementById('posts-pagination');
        const paginationRow = paginationContainer ? paginationContainer.closest('.row') : null;
        
        if (data.pagination) {
          if (paginationContainer) {
            paginationContainer.innerHTML = data.pagination;
            // Show the pagination row container
            if (paginationRow) {
              paginationRow.style.display = 'flex';
            }
          }
        } else {
          // Hide the pagination row container if no pagination
          if (paginationRow) {
            paginationRow.style.display = 'none';
          }
        }
      } else {
        if (projectsContainer) {
          projectsContainer.innerHTML = '<div class="col-12 text-center py-5"><p class="text-muted">Žádné příspěvky nenalezeny.</p></div>';
          // Remove the fixed height
          projectsContainer.style.minHeight = '';
        }

        const paginationContainer = document.getElementById('posts-pagination');
        const paginationRow = paginationContainer ? paginationContainer.closest('.row') : null;
        
        if (paginationContainer) {
          paginationContainer.innerHTML = '';
        }
        if (paginationRow) {
          paginationRow.style.display = 'none';
        }
      }
    })
    .catch(error => {
      console.error('Error filtering posts:', error);
      if (projectsContainer) {
        projectsContainer.innerHTML = '<div class="col-12 text-center py-5"><p class="text-danger">Chyba při načítání příspěvků.</p></div>';
        // Remove the fixed height on error
        projectsContainer.style.minHeight = '';
      }
    });
  }

  // Pagination click handler (delegated)
  document.addEventListener('click', (e) => {
    const link = e.target && e.target.closest && e.target.closest('a.filter-page-link');
    if (!link) return;

    e.preventDefault();
    const page = parseInt(link.getAttribute('data-page'), 10);
    if (!Number.isFinite(page) || page < 1) return;

    // Store current scroll position before content loads
    const currentScrollPosition = window.scrollY;

    // Load new page with scroll restoration enabled
    filterPosts(page, false, true, currentScrollPosition);
  });

  // Load More button functionality
  const loadMoreButton = document.getElementById('load-more-posts');
  if (loadMoreButton) {
    loadMoreButton.addEventListener('click', function() {
      this.disabled = true;
      this.innerHTML = '<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span> Načítání...';
      
      currentPage++;
      
      // Get categories from current filter state
      const categoriesArray = allSelected ? [0] : Array.from(selectedCategories);
      
      // Show loading state
      const projectsContainer = document.getElementById('projects');
      if (projectsContainer) {
        const row = projectsContainer.querySelector('.row') || projectsContainer;
        row.insertAdjacentHTML('beforeend', '<div class="col-12 text-center py-3"><div class="spinner-border text-primary" role="status"><span class="visually-hidden">Načítání...</span></div></div>');
      }
      
      // Fetch more posts via AJAX with append mode
      fetch('/wp-json/msstavby/v1/filter-posts', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          categories: categoriesArray,
          posts_per_page: 6,
          paged: currentPage,
        })
      })
      .then(response => response.json())
      .then(data => {
        // Remove loading indicator and its container
        const loadingIndicators = projectsContainer.querySelectorAll('.col-12.text-center.py-3');
        loadingIndicators.forEach(indicator => {
          indicator.remove();
        });
        
        if (data.success && data.html) {
          // Append new posts
          if (projectsContainer) {
            const row = projectsContainer.querySelector('.row') || projectsContainer;
            const tempDiv = document.createElement('div');
            tempDiv.innerHTML = data.html;
            
            // Extract col elements and append to row
            const cols = tempDiv.querySelectorAll('.col-12');
            cols.forEach(col => row.appendChild(col));
          }
          
          // Check if there are more pages to load by looking for pagination links after current page
          const paginationDiv = document.createElement('div');
          paginationDiv.innerHTML = data.pagination || '';
          const nextPageLinks = paginationDiv.querySelectorAll('a.filter-page-link');
          const hasMorePages = Array.from(nextPageLinks).some(link => parseInt(link.dataset.page) > currentPage);
          
          if (hasMorePages) {
            loadMoreButton.disabled = false;
            loadMoreButton.textContent = 'Další projekty';
          } else {
            loadMoreButton.style.display = 'none';
          }
        } else {
          loadMoreButton.disabled = false;
          loadMoreButton.textContent = 'Další projekty';
        }
      })
      .catch(error => {
        console.error('Error loading more posts:', error);
        loadMoreButton.disabled = false;
        loadMoreButton.textContent = 'Další projekty';
      });
    });
  }

  // Event listeners for filter chips
  filterChips.forEach(chip => {
    chip.addEventListener('click', function() {
      const filter = this.getAttribute('data-filter');

      // Any filter change resets to page 1
      currentPage = 1;
      
      if (filter === 'all') {
        // 'All' selected
        allSelected = true;
        selectedCategories.clear();
        
        // Update UI
        this.classList.add('filter-chip-active');
        filterChips.forEach(c => {
          if (c !== this) {
            c.classList.remove('filter-chip-active');
          }
        });
      } else {
        // Specific category selected
        const categoryId = parseInt(filter);
        allSelected = false;
        
        // Toggle selection
        if (selectedCategories.has(categoryId)) {
          selectedCategories.delete(categoryId);
          this.classList.remove('filter-chip-active');
          
          // If no categories selected, select 'all'
          if (selectedCategories.size === 0) {
            allSelected = true;
            const allChip = document.querySelector('[data-filter="all"]');
            if (allChip) allChip.classList.add('filter-chip-active');
          }
        } else {
          selectedCategories.add(categoryId);
          this.classList.add('filter-chip-active');
          
          // Uncheck 'all' chip
          const allChip = document.querySelector('[data-filter="all"]');
          if (allChip) {
            allChip.classList.remove('filter-chip-active');
          }
        }
      }
      
      filterPosts(1);
      saveFilterState();
      updateURLParams();
    });
  });

  // Apply filter from URL parameters or localStorage on page load
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.has('cat')) {
    applyFilterFromParams(urlParams.get('cat'));
  } else {
    applyFilterFromParams(null);
  }
});
